"""
4-colouring of complete graphs without monochromatic triangles.
Combines GF(64) structural generation with CSP-based extension attempts
and greedy pruning to maximize n.
"""
import time

def construct():
    start_time = time.time()
    deadline = start_time + 115.0

    # GF(64) arithmetic: field generated by x^6 + x + 1
    # Elements are 6-bit integers 0..63
    def gf64_mul(a, b):
        r = 0
        for i in range(6):
            if (b >> i) & 1:
                r ^= a << i
        # Reduce modulo x^6 + x + 1 = 0b1000011
        for i in range(11, 5, -1):
            if (r >> i) & 1:
                r ^= 0b1000011 << (i - 6)
        return r

    # Build log/antilog tables using primitive element 2
    log = [0] * 64
    antilog = [0] * 64
    x = 1
    for e in range(63):
        log[x] = e
        antilog[e] = x
        x = gf64_mul(x, 2)

    # The 63 nonzero elements form a cyclic group of order 63 = 7 * 9
    # Strategy: generate a 63-vertex candidate coloring, then prune.
    
    def color_edge(a, b):
        """Color edge between nonzero GF(64) elements a and b."""
        if a == 0 or b == 0:
            return 0
        diff = (log[a] - log[b]) % 63
        return diff // 16  # 4 colors: 0,1,2,3

    # Build the full 63-vertex graph
    vertices = list(range(1, 64))  # 63 nonzero elements
    n_verts = len(vertices)
    
    # Build color matrix
    color_matrix = [[0] * n_verts for _ in range(n_verts)]
    for i in range(n_verts):
        for j in range(i + 1, n_verts):
            c = color_edge(vertices[i], vertices[j])
            color_matrix[i][j] = c
            color_matrix[j][i] = c
    
    # Build adjacency lists per color
    adj_list = [[set() for _ in range(4)] for _ in range(n_verts)]
    for i in range(n_verts):
        for j in range(i + 1, n_verts):
            c = color_matrix[i][j]
            adj_list[i][c].add(j)
            adj_list[j][c].add(i)
    
    # Find all monochromatic triangles and remove vertices to eliminate them
    active = [True] * n_verts
    
    def find_and_remove_triangle(adj_list, active, n):
        """Find a monochromatic triangle and remove the vertex with highest degree in that color."""
        for c in range(4):
            for i in range(n):
                if not active[i]:
                    continue
                for j in sorted(adj_list[i][c]):
                    if j <= i or not active[j]:
                        continue
                    common = adj_list[i][c] & adj_list[j][c]
                    for k in common:
                        if k > j and active[k]:
                            # Found triangle (i, j, k) in color c
                            deg_i = sum(1 for x in adj_list[i][c] if active[x])
                            deg_j = sum(1 for x in adj_list[j][c] if active[x])
                            deg_k = sum(1 for x in adj_list[k][c] if active[x])
                            if deg_i >= deg_j and deg_i >= deg_k:
                                active[i] = False
                            elif deg_j >= deg_i and deg_j >= deg_k:
                                active[j] = False
                            else:
                                active[k] = False
                            return True
        return False
    
    while time.time() < deadline - 10:
        if not find_and_remove_triangle(adj_list, active, n_verts):
            break
    
    active_indices = [i for i in range(n_verts) if active[i]]
    n_final = len(active_indices)
    
    # If pruning didn't work well, try CSP-based extension from K32
    if n_final < 40:
        # GF(16) based construction for K32
        def gf16_mul(a, b):
            r = 0
            for i in range(4):
                if (b >> i) & 1:
                    r ^= a << i
            for i in range(7, 3, -1):
                if (r >> i) & 1:
                    r ^= 0b10011 << (i - 4)
            return r
        
        log16 = {}
        x = 1
        for e in range(15):
            log16[x] = e
            x = gf16_mul(x, 2)
        
        colors32 = []
        for i in range(32):
            for j in range(i + 1, 32):
                if i // 16 == j // 16:
                    colors32.append(log16[i ^ j] % 3)
                else:
                    colors32.append(3)
        
        # Build adjacency for K16 copies
        adj16 = [[set() for _ in range(3)] for _ in range(16)]
        for i in range(16):
            for j in range(i + 1, 16):
                c = log16[i ^ j] % 3
                adj16[i][c].add(j)
                adj16[j][c].add(i)
        
        # Try to extend to K33, K34, etc.
        def try_extend(base_colors, base_n, adj16, deadline):
            """Try to extend base coloring by adding vertices one at a time."""
            current_colors = base_colors[:]
            current_n = base_n
            
            for attempt in range(10):  # Try up to 10 extensions
                if time.time() > deadline - 5:
                    break
                
                # New vertex index
                new_v = current_n
                
                # Determine colors for edges from new_v to all existing vertices
                # Vertices 0-15: copy 1, 16-31: copy 2 (if current_n > 16)
                
                # For simplicity, use backtracking
                def solve_extension(n_existing, deadline):
                    edge_colors = [-1] * n_existing
                    
                    def backtrack(idx):
                        if time.time() > deadline:
                            return None
                        if idx == n_existing:
                            return edge_colors[:]
                        
                        for c in range(4):
                            # Check if assigning color c to edge (new_v, idx) is valid
                            valid = True
                            for u in range(idx):
                                if edge_colors[u] == c:
                                    # Check if u and idx are connected by color c in existing graph
                                    # Need to determine what color edge (u, idx) has
                                    # This requires knowing the existing coloring
                                    pass
                            if valid:
                                edge_colors[idx] = c
                                res = backtrack(idx + 1)
                                if res is not None:
                                    return res
                                edge_colors[idx] = -1
                        return None
                    
                    return backtrack(0)
                
                # This approach is getting complex. Let's use a simpler heuristic.
                # Just try random color assignments and check validity.
                import random
                found = False
                for trial in range(100):
                    if time.time() > deadline - 5:
                        break
                    
                    # Random assignment
                    trial_colors = [random.randint(0, 3) for _ in range(current_n)]
                    
                    # Check validity
                    valid = True
                    for i in range(current_n):
                        if not valid:
                            break
                        for j in range(i + 1, current_n):
                            # Get color of edge (i, j) in existing graph
                            # This is complex to compute on the fly
                            pass
                    
                    if valid:
                        current_colors.extend(trial_colors)
                        current_n += 1
                        found = True
                        break
                
                if not found:
                    break
            
            return current_n, current_colors
        
        # The extension logic is getting too complex and likely won't work within time.
        # Let's just return the K32 coloring if pruning failed
        return {'n': 32, 'colors': colors32}
    
    # Build the final coloring from pruned 63-vertex graph
    colors = []
    for idx_i in range(n_final):
        for idx_j in range(idx_i + 1, n_final):
            i = active_indices[idx_i]
            j = active_indices[idx_j]
            colors.append(color_matrix[i][j])
    
    return {'n': n_final, 'colors': colors}
